// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type ContactBadgeProps = Record<string, any>;

const ContactBadge: React.FC<ContactBadgeProps> = ({
  backgroundColor = "#FFFFFF",
  transparentBackground = false,
  durationInSeconds = 5,
  emailText = "contact@malloy.studio",
  badgeColor = "#249CDB",
  textColor = "#FFFFFF",
  fontSize = 40,
  paddingX = 60,
  paddingY = 20,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Logic to prevent parser errors on color transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Calculate frames for entry and exit timing
  const totalFrames = durationInSeconds * fps;
  const exitStartFrame = totalFrames - 20;

  // Physics-based spring animations using animation math for entry/exit
  const badgeEntryScale = spring({
    fps,
    frame: frame - 5,
    config: { damping: 14, stiffness: 110 },
  });

  const badgeExitScale = spring({
    fps,
    frame: frame - exitStartFrame,
    config: { damping: 14, stiffness: 110 },
  });

  // Subtracting the exit spring from the entry spring creates a clean transition in and out
  const finalBadgeScale = badgeEntryScale - badgeExitScale;

  // Text internal animations
  const textEntryOpacity = interpolate(frame, [10, 25], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const textExitOpacity = interpolate(
    frame,
    [exitStartFrame, exitStartFrame + 10],
    [1, 0],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );

  const finalOpacity = textEntryOpacity * textExitOpacity;

  const textTranslateY = interpolate(frame, [10, 25], [15, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          backgroundColor: badgeColor,
          borderRadius: 9999, // Perfect pill shape
          padding: `${paddingY}px ${paddingX}px`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${finalBadgeScale})`,
          transition: "none",
        }}
      >
        <span
          style={{
            color: textColor,
            fontFamily: interFamily,
            fontSize: fontSize,
            fontWeight: 700,
            opacity: finalOpacity,
            transform: `translateY(${textTranslateY}px)`,
            transition: "none",
            lineHeight: 1,
            whiteSpace: "nowrap",
          }}
        >
          {emailText}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default ContactBadge;